param([int]$Context=2048,[int]$Seed=0,[string]$OutputRoot='experiments/raw/stock',[string]$ModelPath='models',[string]$Runtime='')
$ErrorActionPreference='Stop'; New-Item -ItemType Directory -Force $OutputRoot | Out-Null
$run='E0-STOCK-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmssZ'); $cmd="powershell.exe -NoProfile -ExecutionPolicy Bypass -File scripts/s03_stock_baseline.ps1 -Context $Context -Seed $Seed -OutputRoot $OutputRoot -ModelPath $ModelPath -Runtime $Runtime"; $files=@(Get-ChildItem $ModelPath -Recurse -File -ErrorAction SilentlyContinue | Where-Object {$_.Extension -in @('.safetensors','.gguf')}); $status=if($files.Count -eq 0){'blocked-no-weights'}elseif(-not $Runtime){'blocked-no-runtime'}else{'pending-inference'}
$j=@{schema='e0-stock-v1';run_id=$run;timestamp_utc=[DateTime]::UtcNow.ToString('o');hypothesis='Stock full-model reference produces coherent output at context 2048';numeric_target='One deterministic output, measured prefill/decode and VRAM/RAM peaks';command=$cmd;model=$ModelPath;quant='NVFP4 or available stock artifact';context=$Context;seed=$Seed;status=$status;model_files=$files.Count;prefill_tok_s=$null;decode_tok_s=$null;vram_peak_bytes=$null;ram_peak_bytes=$null;quality_sample=$null;failure=@{exact_constraint="Local model files: $($files.Count); configured runtime: $([bool]$Runtime)";routes=@('Fetch pinned checkpoint metadata/weights and use compatible stock runtime','Use supported GGUF partial offload reference if matching artifact is available');cheapest_next_experiment='Pin model revision and fetch metadata only, then check runtime architecture support'}}
$j|ConvertTo-Json -Depth 8|Set-Content (Join-Path $OutputRoot 'run.json'); "run=$run status=$status model_files=$($files.Count)"